b=base(); rgb=b.convert('RGB'); L=b.convert('L')
save('a.jp2', rgb, 'JPEG2000')
save('a.j2k', rgb, 'JPEG2000', no_jp2=True)
save('l.jp2', L, 'JPEG2000')
save('rgba.jp2', b, 'JPEG2000')
save('irr.jp2', rgb, 'JPEG2000', irreversible=True)
save('irrl.jp2', L, 'JPEG2000', irreversible=True)
save('lossy.jp2', rgb, 'JPEG2000', quality_mode='rates', quality_layers=[20])
save('layers.jp2', rgb, 'JPEG2000', quality_layers=[40,10,0] if False else [40,10])
save('tiles.jp2', rgb, 'JPEG2000', tile_size=(16,16))
save('rpcl.jp2', rgb, 'JPEG2000', progression='RPCL')
save('pcrl.jp2', rgb, 'JPEG2000', progression='PCRL')
save('cprl.jp2', rgb, 'JPEG2000', progression='CPRL')
save('rlcp.jp2', rgb, 'JPEG2000', progression='RLCP')
save('prec.jp2', rgb, 'JPEG2000', precinct_size=(16,16), num_resolutions=3)
save('cblk.jp2', rgb, 'JPEG2000', codeblock_size=(16,16))
save('offset.jp2', rgb, 'JPEG2000', offset=(5,3))
save('big.jp2', base().resize((300,200)).convert('RGB'), 'JPEG2000', irreversible=True)
save('mct0.jp2', rgb, 'JPEG2000', mct=0)
save('signed.jp2', rgb, 'JPEG2000', signed=True)
save('plt.jp2', rgb, 'JPEG2000', plt=True)
i16=L.point(lambda v: v).convert('I').point(lambda v: v*257).convert('I;16')
save('g16.jp2', i16, 'JPEG2000', adjust=lambda im: im.point(lambda v: v/257).convert('L') if False else Image.frombytes('L', im.size, bytes(x>>8 for x in im.tobytes('raw','I;16')[1::2])) if False else L)
